def level2_plan(frame, active='O', inactive='b', rows=(14,22,30,38,46), cols=(20,28,36)):
    a = frame.ascii.split('\n')
    R,C = len(rows), len(cols)
    grid = [[a[rows[i]+3][cols[j]+3] for j in range(C)] for i in range(R)]
    target = [[None]*C for _ in range(R)]
    minis = []
    for i in range(R):
        for j in range(C):
            blk = [''.join(a[rows[i]+dr][cols[j]+dc] for dc in (1,3,5)) for dr in (1,3,5)]
            if set(''.join(blk)) - {grid[i][j]}:  # pattern cell (not solid)
                minis.append((i,j,blk))
    conflicts=[]
    for (i,j,blk) in minis:
        for di in range(3):
            for dj in range(3):
                ch = blk[di][dj]
                if di==1 and dj==1: continue
                m = {'W':active,'g':inactive}
                if ch not in m: continue
                ti, tj = i+di-1, j+dj-1
                if not (0<=ti<R and 0<=tj<C): continue
                if target[ti][tj] is not None and target[ti][tj]!=m[ch]:
                    conflicts.append((ti,tj,target[ti][tj],m[ch]))
                target[ti][tj]=m[ch]
    return grid, target, minis, conflicts

